// Run a deck through the real CalculiX binary and parse its .dat output.
//
// Every deck goes through the sanitizer (inp-sanitize.mjs) unless the caller
// states it was generated by this worker (deck.mjs). It runs as job "job" in a
// fresh, empty directory: the job name is fixed so nothing from the design
// reaches the command lines ccx builds internally (it calls system() for
// restart-file housekeeping).
//
// Results are read from job.dat only: it holds no dates or host names, so it
// is byte-reproducible. The .frd file carries a timestamp and is not used.

import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { CCX_BIN, runBinary, makeWorkDir, cleanup, toolVersions } from './exec.mjs';
import { sanitizeInp, describeInpViolations } from './inp-sanitize.mjs';

export const DEFAULT_TIMEOUT_MS = 60_000;
export const sha256 = s => 'sha256:' + createHash('sha256').update(s).digest('hex');

const NUM = /^[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?$/;

/**
 * Parse job.dat into blocks: { kind, set, time, rows: number[][] }.
 * kind is the header text before " (" / " for set", e.g. "displacements",
 * "stresses", "global coordinates", "temperatures", "heat flux", "total force".
 * Eigenvalue output is returned separately.
 */
export function parseDat(text) {
  const blocks = [];
  const eigen = [];
  let cur = null, inEigen = false;
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    const hdr = line.match(/^(.+?)\s*(?:\(([^)]*)\))?\s+for set\s+(\S+)\s+and time\s+(\S+)/);
    if (hdr) {
      cur = { kind: hdr[1].trim(), columns: hdr[2] ?? null, set: hdr[3], time: Number(hdr[4]), rows: [] };
      blocks.push(cur); inEigen = false; continue;
    }
    if (/E\s*I\s*G\s*E\s*N\s*V\s*A\s*L\s*U\s*E\s+O\s*U\s*T\s*P\s*U\s*T/.test(line)) { inEigen = true; cur = null; continue; }
    if (/P\s*A\s*R\s*T\s*I\s*C\s*I\s*P\s*A\s*T\s*I\s*O\s*N/.test(line) || /S\s+T\s+E\s+P/.test(line)) { inEigen = false; }
    if (!line) continue;
    const parts = line.split(/\s+/);
    if (!parts.every(p => NUM.test(p))) { if (cur && cur.rows.length) cur = null; continue; }
    const vals = parts.map(Number);
    if (inEigen) {
      // MODE NO | EIGENVALUE | REAL PART rad/time | cycles/time | IMAGINARY rad/time
      if (vals.length >= 4) eigen.push({ mode: vals[0], eigenvalue: vals[1], omega: vals[2], frequency: vals[3] });
      continue;
    }
    if (cur) cur.rows.push(vals);
  }
  return { blocks, eigen };
}

const DECK_PROBLEMS = /Card image cannot be interpreted|does not exist|not applicable|unknown|not recognized/i;

export function classifyCcxFailure({ log = '', timedOut = false, spawnError = null } = {}) {
  if (spawnError) return 'tool_missing';
  if (timedOut) return 'timeout';
  if (/too many cutbacks|divergence|did not converge|no convergence|increment size smaller|singular|zero pivot|not positive definite/i.test(log)) return 'sim_nonconverge';
  return 'tool_error';
}

/**
 * Run a deck. Never throws on solver failure.
 * @param {string} deck
 * @param {{generated?:boolean, files?:Record<string,string>, timeoutMs?:number}} opts
 *   generated: true only for decks built by deck.mjs from typed inputs;
 *   files: the only files a design deck may *INCLUDE (bare names).
 */
export async function runCcx(deck, { generated = false, files = {}, timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  let text = deck;
  if (!generated) {
    const s = sanitizeInp(deck, { files });
    if (!s.ok) {
      return { ok: false, blocked: true, stage: 'sanitize', reason_code: s.reason_code, reason: `deck rejected by the CalculiX sanitizer (not run):\n${describeInpViolations(s.violations)}`, violations: s.violations, deck_sha256: sha256(deck) };
    }
    text = s.deck;
  }
  const versions = await toolVersions();
  const dir = await makeWorkDir('ccx');
  try {
    await writeFile(join(dir, 'job.inp'), text, 'utf8');
    const r = await runBinary(CCX_BIN, ['-i', 'job'], { cwd: dir, timeoutMs });
    const log = `${r.stdout}\n${r.stderr}`;
    let dat = '';
    try { dat = await readFile(join(dir, 'job.dat'), 'utf8'); } catch {}
    const errors = log.split('\n').filter(l => /\*ERROR/.test(l));
    const warnings = log.split('\n').filter(l => /\*WARNING/.test(l));
    const deckProblems = warnings.filter(l => DECK_PROBLEMS.test(l));
    const finished = /Job finished/.test(log);
    const hardFail = Boolean(r.spawnError) || r.timedOut || r.code !== 0 || errors.length > 0 || !finished;
    const base = {
      deck_sha256: sha256(text), dat_sha256: sha256(dat), duration_ms: r.durationMs,
      exit_code: r.code, timed_out: r.timedOut, warnings,
      tool_versions: versions.ids,
    };
    if (hardFail) {
      return { ...base, ok: false, blocked: false, stage: 'run', reason_code: classifyCcxFailure({ log, timedOut: r.timedOut, spawnError: r.spawnError }), reason: (errors.join('\n') || r.spawnError || log.trim().split('\n').slice(-6).join('\n') || 'ccx failed').slice(0, 2000) };
    }
    // A deck we generated must be read by ccx exactly as written. A card it
    // skipped with a warning means the model is not the one we described.
    if (generated && deckProblems.length) {
      return { ...base, ok: false, blocked: false, stage: 'run', reason_code: 'tool_error', reason: `ccx ignored part of the generated deck:\n${deckProblems.join('\n')}`.slice(0, 2000) };
    }
    const parsed = parseDat(dat);
    return { ...base, ok: true, blocked: false, stage: 'run', dat, ...parsed };
  } finally {
    await cleanup(dir);
  }
}

/** First block of a kind (prefix match on the header text) for a set. */
export function block(result, kind, set) {
  return result.blocks.find(b => b.kind.toLowerCase().startsWith(kind) && (!set || b.set.toUpperCase() === set.toUpperCase()));
}
